const icon=(name)=>`<i data-lucide="${name}" aria-hidden="true"></i>`;
const portraitNames=['Maya Chen','Jordan Ellis','Priya Desai','Elena Ruiz','Daniel Kim','Leah Monroe'];
const avatar=(name,large=false)=>{const idx=portraitNames.indexOf(name);return idx<0?initialsAvatar(name,large):`<span class="cu-avatar cu-portrait ${large?'large':''}" role="img" aria-label="${escape(name)}" style="background-image:url(assets/person-${idx}.webp)"></span>`;};
const photo=(index,cls='')=>`<div class="cu-photo ${cls}" aria-hidden="true" style="background-image:url(assets/scene-${index}.webp)"></div>`;
