  const filtered=all.filter(t=>(state.filter==='All'||t.category===state.filter)&&`${t.title} ${t.body} ${t.author}`.toLowerCase().includes(query));
  const selected=filtered.find(t=>t.id===state.thread)||filtered[0]||null;
